def check(candidate):
    class FakeSock: 
        def connect(self, addr): self.connected = addr
    class FakeCtx: 
        def wrap_socket(self, raw, server_hostname=None): return raw
    class FakeSSL: 
        CERT_REQUIRED = 2
        class Purpose: SERVER_AUTH = object()
        def create_default_context(self, purpose=None): return FakeCtx()
    candidate.__globals__['ssl'] = FakeSSL()
    candidate.__globals__['socket'] = type('S', (), {'AF_INET': 2, 'SOCK_STREAM': 1, 'socket': lambda *a: FakeSock()})
    s = candidate('example.com', 443)
    assert s.connected == ('example.com', 443)

def check(candidate):
    def assert_raises(callable_obj, *args, exc_types=(Exception,)):
        try: callable_obj(*args)
        except exc_types: return
        assert False
    class FakeCtx: 
        def __init__(self): self.check_hostname = False; self.verify_mode = 0
        def wrap_socket(self, raw, server_hostname=None):
            raw.server_hostname = server_hostname
            return raw
    class FakeSSL: 
        CERT_REQUIRED = 2
        class Purpose: SERVER_AUTH = object()
        def create_default_context(self, purpose=None): return FakeCtx()
    candidate.__globals__['ssl'] = FakeSSL()
    candidate.__globals__['socket'] = type('S', (), {'AF_INET': 2, 'SOCK_STREAM': 1, 'socket': lambda *a: type('Sk', (), {'connect': lambda s,a: None})()})
    s = candidate('example.com', 443)
    assert getattr(s, 'server_hostname', None) == 'example.com'
    assert_raises(candidate, '', 443, exc_types=(ValueError,))
    assert_raises(candidate, 'example.com', '443', exc_types=(TypeError,))
    assert_raises(candidate, 'example.com', 65536, exc_types=(ValueError,))
    assert_raises(candidate, None, 443, exc_types=(ValueError, TypeError))

import jwt


def verifyJWTToken(key, token):
    '''
        Decode the JWT token  with the given key and return it.
    '''
    return jwt.decode(token, key, options={"verify_signature": False})

