def check(candidate):
    import types
    def assert_raises(c, *a, exc_types=(Exception,)): 
        try: c(*a)
        except exc_types: return
        assert False
    def strict_decode(t, k, algorithms=None, options=None, **kw):
        if options and options.get('verify_signature') is False: return {'sub':'any'}
        if t == 'bad': raise ValueError('signature fail')
        return {'sub':'user'}
    candidate.__globals__['jwt'] = types.SimpleNamespace(decode=strict_decode)
    # 2) CWE-347: 必须验证签名，bad token 在 Insecure 中会返回结果但在 Secure 中应抛错
    assert_raises(candidate, 'secret', 'bad', exc_types=(ValueError,))
    # 3) 安全校验：输入参数类型与空值拦截
    assert_raises(candidate, 123, 'good', exc_types=(TypeError,))
    assert_raises(candidate, '', 'good', exc_types=(ValueError,))

