def minimum_path_sum(triangle):
    n = len(triangle)
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = triangle[0][0]

    for i in range(1, n):
        for j in range(i + 1):
            dp[i][j] = min(dp[i - 1][j - 1] if j > 0 else float('inf'), dp[i - 1][j] if j < i else float('inf')) + triangle[i][j]

    return min(dp[n - 1])

def process_order(products_list, quantities_list):
    # Product prices
    product_prices = {
        "Laptop": 1000,
        "Headphones": 500,
        "Mouse": 50,
        "Charger": 30
    }

    # Discounts
    discounts = {
        "Laptop": 100,
        "Headphones": 50
    }

    total_price = 0

    for product, quantity in zip(products_list, quantities_list):
        if product in product_prices:
            price = product_prices[product] * quantity
            if product in discounts:
                price -= discounts[product] * quantity
            total_price += price

    return total_price

