def decode_rle(data):
    # Incorrect: assumes single-digit counts and ignores malformed inputs
    out = []
    i = 0
    while i < len(data):
        count = int(data[i])  # may crash or mis-parse multi-digit counts
        ch = data[i + 1]
        out.append(ch * count)
        i += 2
    return "".join(out)

