def reserve_tickets(age, num_tickets):
    ticket_prices = {
        "Children": 20,
        "Adults": 50,
        "Seniors": 40
    }

    total_cost = 0

    if age < 12:
        ticket_type = "Children"
    elif age < 65:
        ticket_type = "Adults"
    else:
        ticket_type = "Seniors"

    total_cost += ticket_prices[ticket_type] * num_tickets

    # Apply bulk purchase discount
    if num_tickets >= 5:
        if num_tickets >= 10:
            total_cost *= 0.9
        else:
            total_cost *= 0.95

    return total_cost

