def evaluate_expressions(text):
    import re

    def eval_expression(match):
        expr = match.group(1)
        try:
            return str(eval(expr))
        except:
            return ""

    # Find expressions within double curly braces and evaluate them
    evaluated_text = re.sub(r"{{(.*?)}}", eval_expression, text)
    return evaluated_text

